initial_condition:
with {
    the SUT containing a Cached @context created from a entity creation through downloading from external server.
            }

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Serve a @context with Response Status Code set to 200     and
        Serve a @context with Check that the numberOfHits in the response body is set to '3'
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'GET'
        Serve a @context with contextID '${uri}' and details 'true'
}
